unsafe {
    let mut statenr: c_int = 0;
    let mut transnr: c_int = 0;
    let mut state: xmlRegStatePtr = ::core::ptr::null_mut::<xmlRegState>();
    let mut has_epsilon: c_int = 0;
    if (*ctxt).states.is_null() {
        return;
    }
    xmlFAEliminateSimpleEpsilonTransitions(ctxt);

    let nb_states = (*ctxt).nbStates;
    let states = (*ctxt).states;

    statenr = 0 as c_int;
    while statenr < nb_states {
        let state_slot = states.offset(statenr as isize);
        state = *state_slot;
        if !state.is_null()
            && (*state).type_0 as c_uint
                == XML_REGEXP_UNREACH_STATE as c_int as c_uint
        {
            xmlRegFreeState(state);
            *state_slot = ::core::ptr::null_mut::<xmlRegState>();
        }
        statenr += 1;
    }
    has_epsilon = 0 as c_int;
    statenr = nb_states - 1 as c_int;
    while statenr >= 0 as c_int {
        state = *states.offset(statenr as isize);
        if !state.is_null() {
            if (*state).nbTrans == 0 as c_int
                && (*state).type_0 as c_uint
                    != XML_REGEXP_FINAL_STATE as c_int as c_uint
            {
                (*state).type_0 = XML_REGEXP_SINK_STATE;
            }
            let nb_trans = (*state).nbTrans;
            let trans_base = (*state).trans;
            transnr = 0 as c_int;
            while transnr < nb_trans {
                let trans = trans_base.offset(transnr as isize);
                if (*trans).atom.is_null() && (*trans).to >= 0 as c_int {
                    if (*trans).to == statenr {
                        (*trans).to = -(1 as c_int);
                    } else if (*trans).count < 0 as c_int {
                        let newto: c_int = (*trans).to;
                        has_epsilon = 1 as c_int;
                        (*trans).to = -(2 as c_int);
                        (*state).mark = XML_REGEXP_MARK_START;
                        xmlFAReduceEpsilonTransitions(ctxt, statenr, newto, (*trans).counter);
                        xmlFAFinishReduceEpsilonTransitions(ctxt, newto);
                        (*state).mark = XML_REGEXP_MARK_NORMAL;
                    }
                }
                transnr += 1;
            }
        }
        statenr -= 1;
    }
    if has_epsilon != 0 {
        statenr = 0 as c_int;
        while statenr < nb_states {
            state = *states.offset(statenr as isize);
            if !state.is_null() {
                let nb_trans = (*state).nbTrans;
                let trans_base = (*state).trans;
                transnr = 0 as c_int;
                while transnr < nb_trans {
                    let trans: xmlRegTransPtr = trans_base.offset(transnr as isize);
                    if (*trans).atom.is_null()
                        && (*trans).count < 0 as c_int
                        && (*trans).to >= 0 as c_int
                    {
                        (*trans).to = -(1 as c_int);
                    }
                    transnr += 1;
                }
            }
            statenr += 1;
        }
    }
    statenr = 0 as c_int;
    while statenr < nb_states {
        state = *states.offset(statenr as isize);
        if !state.is_null() {
            (*state).reached = XML_REGEXP_MARK_NORMAL;
        }
        statenr += 1;
    }
    state = *states.offset(0 as c_int as isize);
    if !state.is_null() {
        (*state).reached = XML_REGEXP_MARK_START;
    }
    while !state.is_null() {
        let mut target: xmlRegStatePtr = ::core::ptr::null_mut::<xmlRegState>();
        (*state).reached = XML_REGEXP_MARK_VISITED;
        let nb_trans = (*state).nbTrans;
        let trans_base = (*state).trans;
        transnr = 0 as c_int;
        while transnr < nb_trans {
            let trans = trans_base.offset(transnr as isize);
            if (*trans).to >= 0 as c_int
                && (!(*trans).atom.is_null() || (*trans).count >= 0 as c_int)
            {
                let newto_0: c_int = (*trans).to;
                let next_state_slot = states.offset(newto_0 as isize);
                let next_state = *next_state_slot;
                if !next_state.is_null() {
                    if (*next_state).reached as c_uint
                        == XML_REGEXP_MARK_NORMAL as c_int as c_uint
                    {
                        (*next_state).reached = XML_REGEXP_MARK_START;
                        target = next_state;
                    }
                }
            }
            transnr += 1;
        }
        if target.is_null() {
            statenr = 1 as c_int;
            while statenr < nb_states {
                state = *states.offset(statenr as isize);
                if !state.is_null()
                    && (*state).reached as c_uint
                        == XML_REGEXP_MARK_START as c_int as c_uint
                {
                    target = state;
                    break;
                } else {
                    statenr += 1;
                }
            }
        }
        state = target;
    }
    statenr = 0 as c_int;
    while statenr < nb_states {
        let state_slot = states.offset(statenr as isize);
        state = *state_slot;
        if !state.is_null()
            && (*state).reached as c_uint
                == XML_REGEXP_MARK_NORMAL as c_int as c_uint
        {
            xmlRegFreeState(state);
            *state_slot = ::core::ptr::null_mut::<xmlRegState>();
        }
        statenr += 1;
    }
}

